SELECT status, CASE WHEN YEAR(end_date) < 2024 THEN 'before_2024' WHEN YEAR(end_date) = 2024 THEN '2024' ELSE 'after_2024' END AS end_cohort, CASE WHEN monthly_fee >= 184 THEN 'high' WHEN monthly_fee >= 120 THEN 'mid' ELSE 'low' END AS monthly_fee_bucket, ROUND((100 * SUM(CASE WHEN status = 'CANCELLED' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_cancelled, COUNT(CASE WHEN status = 'PAUSED' THEN 1 END) AS paused_count FROM subscriptions WHERE MONTH(end_date) IN (4, 10, 12) AND customer_id = 15 AND monthly_fee <= 90 GROUP BY status, CASE WHEN YEAR(end_date) < 2024 THEN 'before_2024' WHEN YEAR(end_date) = 2024 THEN '2024' ELSE 'after_2024' END, CASE WHEN monthly_fee >= 184 THEN 'high' WHEN monthly_fee >= 120 THEN 'mid' ELSE 'low' END ORDER BY monthly_fee_bucket, end_cohort;
